import{_ as e,c as n,o as i,aj as l}from"./chunks/framework.rJ-FfUda.js";const m=JSON.parse('{"title":"vim","description":"","frontmatter":{"title":"vim","hugoSource":"computer-science/vim.md","outline":[1,6]},"headers":[],"relativePath":"computer-science/2026-11-17-vim.md","filePath":"computer-science/2026-11-17-vim.md"}'),r={name:"computer-science/2026-11-17-vim.md"};function s(t,a,o,p,h,c){return i(),n("div",null,[...a[0]||(a[0]=[l(`<ul><li><a href="http://www.study-area.org/tips/vim/index.html" target="_blank" rel="noreferrer">大家來學VIM（一個歷久彌新的編輯器）</a></li><li><a href="https://vim.nauxscript.com/" target="_blank" rel="noreferrer">Just Vim It</a></li></ul><h1 id="shortcut" tabindex="-1">shortcut <a class="header-anchor" href="#shortcut" aria-label="Permalink to “shortcut”">​</a></h1><ul><li>删除 光标到行末 <code>d$</code></li><li>vim 打开文件刷新文件 <code>:e</code></li></ul><h1 id="nvim" tabindex="-1">nvim <a class="header-anchor" href="#nvim" aria-label="Permalink to “nvim”">​</a></h1><ul><li><a href="https://neovim.io/" target="_blank" rel="noreferrer">neovim.io</a><ul><li>直接用brew安装就行 <code>brew install neovim</code></li></ul></li><li>第一步肯定是要把插件管理工具安装一下 <ul><li><a href="https://github.com/junegunn/vim-plug" target="_blank" rel="noreferrer">junegunn/vim-plug</a><ul><li>直接运行文档中linux的安装命令</li></ul></li></ul></li></ul><h2 id="indent" tabindex="-1">indent <a class="header-anchor" href="#indent" aria-label="Permalink to “indent”">​</a></h2><ul><li><a href="https://vi.stackexchange.com/questions/42406/how-can-i-make-neovim-wrap-lines-in-respect-to-indentation" target="_blank" rel="noreferrer">How can I make (Neo)Vim wrap lines in respect to indentation?</a><ul><li>这个可以解决缩进换行的问题，很棒！</li></ul></li></ul><h2 id="clipboard-剪贴板" tabindex="-1">clipboard 剪贴板 <a class="header-anchor" href="#clipboard-剪贴板" aria-label="Permalink to “clipboard 剪贴板”">​</a></h2><p>直接在配置文件中添加这两行，就可以了</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>vnoremap y &quot;+y</span></span>
<span class="line"><span>set clipboard+=unnamedplus</span></span></code></pre></div><h2 id="quickfix" tabindex="-1">quickfix <a class="header-anchor" href="#quickfix" aria-label="Permalink to “quickfix”">​</a></h2><ul><li><a href="https://zhuanlan.zhihu.com/p/71778294" target="_blank" rel="noreferrer">VIM学习笔记 QuickFix</a></li></ul><h2 id="lazyvim" tabindex="-1">LazyVim <a class="header-anchor" href="#lazyvim" aria-label="Permalink to “LazyVim”">​</a></h2><ul><li><a href="https://www.lazyvim.org/" target="_blank" rel="noreferrer">lazyvim org</a></li><li><a href="https://yelog.org/2024/08/02/write-markdown-in-neovim-experience-and-tips/" target="_blank" rel="noreferrer">用 neovim 写 markdown 是一种什么样的体验(含技巧)</a></li></ul><h2 id="markdown" tabindex="-1">markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to “markdown”">​</a></h2><ul><li>theCW <ul><li><a href="https://www.bilibili.com/video/BV1ox411R7bo" target="_blank" rel="noreferrer">不影响听课的高效率记笔记方法：Vim + Markdown - 教学与配置</a></li></ul></li><li><a href="https://github.com/iamcco/markdown-preview.nvim" target="_blank" rel="noreferrer">iamcco/markdown-preview.nvim</a></li><li><a href="https://linkarzu.com/posts/neovim/markdown-setup-2024/" target="_blank" rel="noreferrer">My neovim markdown setup in 2024</a></li><li><a href="https://github.com/tadmccorkle/markdown.nvim" target="_blank" rel="noreferrer">tadmccorkle/markdown.nvim</a></li><li><a href="https://github.com/cnshsliu/smp.nvim" target="_blank" rel="noreferrer">cnshsliu/smp.nvim</a></li><li><a href="https://github.com/MeanderingProgrammer/render-markdown.nvim" target="_blank" rel="noreferrer">MeanderingProgrammer/render-markdown.nvim</a><ul><li>这个插件可以直接在 neovim 中直接 render markdown 文件</li><li>但是安装只提供了 lua 的安装方式</li></ul></li></ul><h3 id="outline-nvim" tabindex="-1">outline.nvim <a class="header-anchor" href="#outline-nvim" aria-label="Permalink to “outline.nvim”">​</a></h3><ul><li><a href="https://github.com/hedyhli/outline.nvim" target="_blank" rel="noreferrer">hedyhli/outline.nvim</a><ul><li>这个插件太优秀了！</li></ul></li></ul><hr><p>解决 outline 左箭头和下箭头乱码的问题</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>symbol_folding = {</span></span>
<span class="line"><span>  autofold_depth = false,</span></span>
<span class="line"><span>  markers = { &#39;&gt;&#39;, &#39;∨&#39; },</span></span>
<span class="line"><span>}</span></span></code></pre></div><hr><p><a href="https://stackoverflow.com/questions/3828606/vim-markdown-folding" target="_blank" rel="noreferrer">Vim Markdown Folding?</a></p><p>直接在配置文件中加上下面这段</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>function! MarkdownLevel()</span></span>
<span class="line"><span>    if getline(v:lnum) =~ &#39;^# .*$&#39;</span></span>
<span class="line"><span>        return &quot;&gt;1&quot;</span></span>
<span class="line"><span>    endif</span></span>
<span class="line"><span>    if getline(v:lnum) =~ &#39;^## .*$&#39;</span></span>
<span class="line"><span>        return &quot;&gt;2&quot;</span></span>
<span class="line"><span>    endif</span></span>
<span class="line"><span>    if getline(v:lnum) =~ &#39;^### .*$&#39;</span></span>
<span class="line"><span>        return &quot;&gt;3&quot;</span></span>
<span class="line"><span>    endif</span></span>
<span class="line"><span>    if getline(v:lnum) =~ &#39;^#### .*$&#39;</span></span>
<span class="line"><span>        return &quot;&gt;4&quot;</span></span>
<span class="line"><span>    endif</span></span>
<span class="line"><span>    if getline(v:lnum) =~ &#39;^##### .*$&#39;</span></span>
<span class="line"><span>        return &quot;&gt;5&quot;</span></span>
<span class="line"><span>    endif</span></span>
<span class="line"><span>    if getline(v:lnum) =~ &#39;^###### .*$&#39;</span></span>
<span class="line"><span>        return &quot;&gt;6&quot;</span></span>
<span class="line"><span>    endif</span></span>
<span class="line"><span>    return &quot;=&quot; </span></span>
<span class="line"><span>endfunction</span></span>
<span class="line"><span>au BufEnter *.md setlocal foldexpr=MarkdownLevel()  </span></span>
<span class="line"><span>au BufEnter *.md setlocal foldmethod=expr</span></span></code></pre></div><h2 id="搜索插件" tabindex="-1">搜索插件 <a class="header-anchor" href="#搜索插件" aria-label="Permalink to “搜索插件”">​</a></h2><h3 id="fzf" tabindex="-1">fzf <a class="header-anchor" href="#fzf" aria-label="Permalink to “fzf”">​</a></h3><ul><li>note 只能搜索文件，不能进行全文搜索</li><li>安装<code>fzf</code><ul><li><code>brew install fzf</code></li></ul></li><li>安装 fzf 的vim的插件 <ul><li><a href="https://github.com/junegunn/fzf.vim" target="_blank" rel="noreferrer">junegunn/fzf.vim</a></li></ul></li><li>Reference <ul><li><a href="https://www.bilibili.com/video/BV1bJ411s74r" target="_blank" rel="noreferrer">FZF：终端下的文件查找器【猛男必备233333】</a></li></ul></li></ul><h3 id="telescope" tabindex="-1">telescope <a class="header-anchor" href="#telescope" aria-label="Permalink to “telescope”">​</a></h3><ul><li><a href="https://github.com/nvim-telescope/telescope.nvim" target="_blank" rel="noreferrer">nvim-telescope/telescope.nvim</a></li><li>支持全文搜索需要额外安装这个插件 <ul><li><a href="https://github.com/BurntSushi/ripgrep" target="_blank" rel="noreferrer">BurntSushi/ripgrep</a></li></ul></li></ul><hr><p>搜索结果换行的配置，vimscript 版本</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>lua &lt;&lt;EOF</span></span>
<span class="line"><span>require(&quot;telescope&quot;).setup {</span></span>
<span class="line"><span>  defaults = {</span></span>
<span class="line"><span>    wrap_results = true,</span></span>
<span class="line"><span>  },</span></span>
<span class="line"><span>  pickers = {</span></span>
<span class="line"><span>    oldfiles = {</span></span>
<span class="line"><span>      initial_mode = &quot;normal&quot;</span></span>
<span class="line"><span>    }</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>EOF</span></span></code></pre></div><h2 id="美化" tabindex="-1">美化 <a class="header-anchor" href="#美化" aria-label="Permalink to “美化”">​</a></h2><ul><li><a href="https://www.reddit.com/r/neovim/comments/q8uvpa/looking_for_airline_replacement/" target="_blank" rel="noreferrer">Looking for airline replacement</a></li><li><a href="https://github.com/famiu/feline.nvim" target="_blank" rel="noreferrer">famiu/feline.nvim</a></li></ul><h3 id="buffer" tabindex="-1">buffer <a class="header-anchor" href="#buffer" aria-label="Permalink to “buffer”">​</a></h3><ul><li><a href="https://github.com/akinsho/bufferline.nvim" target="_blank" rel="noreferrer">akinsho/bufferline.nvim</a><ul><li>需要安装一个字体，不然图标显示不出来很丑 <ul><li><a href="https://github.com/ryanoasis/nerd-fonts" target="_blank" rel="noreferrer">ryanoasis/nerd-fonts</a><ul><li><code>brew install font-hack-nerd-font</code></li></ul></li></ul></li></ul></li><li><a href="https://github.com/ap/vim-buftabline" target="_blank" rel="noreferrer">ap/vim-buftabline</a><ul><li>这个 repository 里面讲了一些和 buffer 有关的只是和维护者对 buffer 的一些思考</li></ul></li></ul><h2 id="dropbar-nvim" tabindex="-1">dropbar.nvim <a class="header-anchor" href="#dropbar-nvim" aria-label="Permalink to “dropbar.nvim”">​</a></h2><h2 id="cellular-automation" tabindex="-1">cellular.automation <a class="header-anchor" href="#cellular-automation" aria-label="Permalink to “cellular.automation”">​</a></h2><h1 id="vimscript" tabindex="-1">vimscript <a class="header-anchor" href="#vimscript" aria-label="Permalink to “vimscript”">​</a></h1><ul><li><a href="https://zhuanlan.zhihu.com/p/37352209" target="_blank" rel="noreferrer">VimScript 五分钟入门（翻译）</a></li></ul><h1 id="lua" tabindex="-1">lua <a class="header-anchor" href="#lua" aria-label="Permalink to “lua”">​</a></h1><ul><li>theCW <ul><li><a href="https://www.bilibili.com/video/BV14z4y1E7o5" target="_blank" rel="noreferrer">用Lua重新配置Neovim，我一周就干了个这。｜ Neovim Vlog[0]</a></li><li><a href="https://www.bilibili.com/video/BV13k4y1V7v3" target="_blank" rel="noreferrer">Lua实战：加强Neovim｜Neovim Vlog[1]</a></li><li><a href="https://github.com/theniceboy/nvim/tree/lua-migration" target="_blank" rel="noreferrer">theCW的lua 配置</a></li></ul></li><li><a href="https://wsdjeg.net/from-vimscript-to-lua/" target="_blank" rel="noreferrer">从 VimScipt 切换至 Lua</a></li></ul>`,43)])])}const d=e(r,[["render",s]]);export{m as __pageData,d as default};
